function renderAnalytics(v){const trend=(v.trend&&v.trend.length?v.trend:[{cycle:0,meScore:v.me.score,rivalScore:v.rival.score}]),W=720,H=180,P=28,vals=trend.flatMap(x=>[x.meScore,x.rivalScore]),lo=Math.floor(Math.min(...vals)/50)*50,hi=Math.max(lo+100,Math.ceil(Math.max(...vals)/50)*50),x=i=>P+(trend.length===1?(W-2*P):i*(W-2*P)/(trend.length-1)),y=n=>H-P-(n-lo)*(H-2*P)/(hi-lo),path=key=>trend.map((p,i)=>`${i?'L':'M'}${x(i).toFixed(1)},${y(p[key]).toFixed(1)}`).join(' '),last=trend[trend.length-1],grid=[0,.25,.5,.75,1].map(f=>{const yy=P+f*(H-2*P),val=Math.round(hi-f*(hi-lo));return`<line class="chart-grid" x1="${P}" y1="${yy}" x2="${W-P}" y2="${yy}"/><text class="chart-label" x="2" y="${yy+3}">${val}</text>`}).join('');$('#trendChart').innerHTML=`<svg class="trend-chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="Enterprise value trend"><defs><linearGradient id="scoreArea" x1="0" y1="0" x2="0" y2="1"><stop stop-color="var(--bank-me)"/><stop offset="1" stop-color="var(--bank-me)" stop-opacity="0"/></linearGradient></defs>${grid}<path class="chart-area" d="${path('meScore')} L${x(trend.length-1)},${H-P} L${x(0)},${H-P} Z"/><path class="chart-me" d="${path('meScore')}"/><path class="chart-rival" d="${path('rivalScore')}"/><circle class="chart-dot-me" cx="${x(trend.length-1)}" cy="${y(last.meScore)}" r="4"/><circle class="chart-dot-rival" cx="${x(trend.length-1)}" cy="${y(last.rivalScore)}" r="4"/><text class="chart-value" x="${P}" y="14">YOU ${Number(last.meScore).toFixed(1)}</text><text class="chart-value" text-anchor="end" x="${W-P}" y="14">RIVAL ${Number(last.rivalScore).toFixed(1)}</text><text class="chart-label" x="${P}" y="${H-4}">OPEN</text><text class="chart-label" text-anchor="end" x="${W-P}" y="${H-4}">CYCLE ${last.cycle}</text></svg>`;const gap=v.me.score-v.rival.score;$('#scoreGap').textContent=`${gap>=0?'LEADING':'TRAILING'} ${Math.abs(gap).toFixed(1)} VALUE`;$('#scoreGap').className=`small ${gap>=0?'good':'bad'}`;const maxAsset=Math.max(v.me.stats.deposits,v.rival.stats.deposits,v.me.stats.loans,v.rival.stats.loans,1),bar=(label,a,b)=>`<div class="micro">${label}</div><div class="versus-row"><span class="versus-bank">${money(a)}</span><div style="width:125px"><div class="versus-bar"><span class="me" style="width:${a/maxAsset*100}%"></span></div><div class="versus-bar" style="margin-top:3px"><span class="rival" style="width:${b/maxAsset*100}%"></span></div></div><span class="versus-bank rival">${money(b)}</span></div>`;$('#portfolioIntel').innerHTML=`<h3>BALANCE-SHEET CONTEST</h3><div class="row micro"><span>YOU // ${esc(v.me.name)}</span><span>RIVAL // ${esc(v.rival.name)}</span></div>${bar('DEPOSITS',v.me.stats.deposits,v.rival.stats.deposits)}${bar('LOANS',v.me.stats.loans,v.rival.stats.loans)}`;const liquidity=v.me.stats.cash/Math.max(1,v.me.stats.deposits)*100,risk=v.me.stats.compliance+v.me.stats.attention,initials=v.me.doctrine.name.split(' ').map(x=>x[0]).join('').slice(0,2),rivalStrategy=v.rival.primaryStrategy?v.strategyBranches[v.rival.primaryStrategy].name:'UNCOMMITTED';$('#doctrineIntel').innerHTML=`<h3>INSTITUTIONAL CHARACTER &amp; SIGNALS</h3><div class="doctrine-line"><div class="doctrine-mark">${esc(initials)}</div><div><b>${esc(v.me.doctrine.name)}</b><div class="micro muted">${esc(v.me.doctrine.desc)}</div><div class="micro">RIVAL ROADMAP // <b>${esc(rivalStrategy)}</b> · BOARD CONCESSIONS ${v.rival.boardConcessions}</div></div></div><div class="doctrine-profile">${Object.entries(v.me.doctrineProfile).sort((a,b)=>b[1]-a[1]).map(([k,share])=>`<div class="profile-row ${k===v.me.doctrine.key?'lead':''}"><span>${esc(v.doctrines[k].name)}</span><div class="profile-bar"><span style="width:${Math.round(share*100)}%"></span></div><b>${Math.round(share*100)}%</b></div>`).join('')}<div class="micro muted">Character is read from what you have built and how you staff the bank. It shifts as you do.</div></div><div class="signal-grid"><div class="signal ${liquidity>=4?'safe':liquidity>=2?'watch':'hot'}"><span>LIQUIDITY</span><b>${liquidity.toFixed(1)}%</b></div><div class="signal ${risk<65?'safe':'hot'}"><span>RISK LOAD</span><b>${risk}</b></div><div class="signal ${v.me.stats.lastProfit>=0?'safe':'hot'}"><span>PROFIT</span><b>${money(v.me.stats.lastProfit)}</b></div></div><div class="reg-standing"><div class="micro muted">REGULATORY STANDING</div><div class="reg-row"><span class="reg-who">YOU</span><span class="reg-tier ${tierClass(v.me.capitalTier.key)}">${esc(v.me.capitalTier.name)}</span><span class="reg-ratio">${v.me.capitalRatio.toFixed(1)}%</span></div><div class="reg-row"><span class="reg-who rival">RIVAL</span><span class="reg-tier ${tierClass(v.rival.capitalTier.key)}">${esc(v.rival.capitalTier.name)}</span><span class="reg-ratio">${v.rival.capitalRatio.toFixed(1)}%</span></div>${v.me.distress?`<div class="micro bad">RECEIVERSHIP WARNING // ${v.me.distress} of ${v.receivershipCycles} critical cycles used. Raise capital or shrink the balance sheet.</div>`:''}${v.rival.distress?`<div class="micro good">Your rival has burned ${v.rival.distress} of ${v.receivershipCycles} cycles before receivership.</div>`:''}<div class="micro muted">${esc(v.me.capitalTier.text)}</div></div>`}
function renderDecision(v){
 renderAnalytics(v);$('#eventName').textContent=v.event.name;$('#eventText').textContent=v.event.text;
 const cash=n=>'$'+Math.round(Math.abs(n)).toLocaleString(),signed=n=>(n<0?'−':n>0?'+':'')+cash(n),budget=E.planBudget(v.me,draft,v);
 const names={staff:'Bankers',reputation:'Reputation',morale:'Morale',compliance:'Compliance risk',attention:'Corporate attention',influence:'Influence',momentum:'Momentum'};
 $('#decisionGrid').innerHTML=['a','b'].map(k=>{
  const q=E.decisionQuote(v.me,v.event,k),resources=Object.entries(names).filter(([key])=>q.changes[key]).map(([key,label])=>label+' '+(q.changes[key]>0?'+':'')+q.changes[key]).join(' · ');
  const funding=[q.securitiesSold?'Securities sold '+cash(q.securitiesSold):'',q.loansSold?'Loans sold '+cash(q.loansSold):'',q.borrowed?'New emergency debt '+cash(q.borrowed):'',q.fundingLoss?'Funding-sale loss '+cash(q.fundingLoss):''].filter(Boolean).join(' · ');
  return '<button type="button" class="select-card '+(draft.decision===k?'selected':'')+'" data-decision="'+k+'" '+(v.me.submitted?'disabled':'')+'><b>'+esc(k==='a'?v.event.a:v.event.b)+'</b><div class="micro">'+esc(k==='a'?v.event.ad:v.event.bd)+'</div><div class="micro"><b>Immediate cash paid '+cash(q.paid)+(q.received?' · received '+cash(q.received):'')+'</b><br>Cash balance change '+signed(q.cashChange)+' · '+(q.accounting?'Equity':'Capital')+' change '+signed(q.equityChange)+(resources?'<br>'+esc(resources):'')+'</div>'+(funding?'<div class="micro warn">'+esc(funding)+'</div>':'')+(budget.total>q.spendingLimitAfter?'<div class="micro warn">Draft commitments exceed cash'+(q.accounting?' / capital capacity':'')+' immediately after this call. Later income or shocks can change execution.</div>':'')+'</button>';
}).join('')+'<p class="micro muted" style="grid-column:1/-1">Immediate-stage estimate on your current bank before other staged orders, not a full turn forecast. Executive calls are outside the plan-budget total; funding may sell assets or add debt. Subsequent operations, delayed consequences, rival actions and market outcomes are excluded. Nothing is submitted here.</p>';
 const identity=game||view,owner=v.me.id,cycle=v.cycle;
 $$('[data-decision]').forEach(b=>b.addEventListener('click',()=>{const now=currentView();if((game||view)!==identity||now?.me.id!==owner||now.cycle!==cycle||now.me.submitted||now.gameOver||gh.active&&gh.paused)return;draft.decision=b.dataset.decision;renderDecision(now);renderReady(now)}));
}
function isoBuilding(x,y,h,w=14){const d=w*.55,top=y-h;return`<g><polygon class="building-left" points="${x-w},${top} ${x},${top+d} ${x},${y+d} ${x-w},${y}"/><polygon class="building-right" points="${x},${top+d} ${x+w},${top} ${x+w},${y} ${x},${y+d}"/><polygon class="building-top" points="${x-w},${top} ${x},${top-d} ${x+w},${top} ${x},${top+d}"/><path class="building-window" d="M${x-w+3},${top+8} L${x-3},${top+12} M${x+3},${top+12} L${x+w-3},${top+8}" stroke-width="2"/></g>`}
function districtArt(k,t){const p=mapPosition(k,t),x=p[0]*10,y=p[1]*6.5,[,cls]=ownerLabel(t.shares[0]),state=t.unlocked?cls:'locked',depth=10,base=`<polygon class="district-side-left" points="${x-55},${y} ${x},${y+29} ${x},${y+29+depth} ${x-55},${y+depth}"/><polygon class="district-side-right" points="${x},${y+29} ${x+55},${y} ${x+55},${y+depth} ${x},${y+29+depth}"/><polygon class="district-base district-top ${state}" points="${x},${y-29} ${x+55},${y} ${x},${y+29} ${x-55},${y}"/>`,park=['agricultural','suburbs','resort'].includes(k)?`<ellipse class="park" cx="${x-20}" cy="${y+3}" rx="19" ry="10"/><circle class="tree" cx="${x-27}" cy="${y-4}" r="5"/><circle class="tree" cx="${x-14}" cy="${y}" r="6"/>`:'',count=t.unlocked?Math.min(4,Math.max(2,Math.round(t.value/9))):2,buildings=Array.from({length:count},(_,i)=>isoBuilding(x-23+i*15,y+9-i*4,30+t.value*1.15-i*5,11+i*1.5)).join(''),pins=Array.from({length:Math.min(6,t.branches[0]+t.branches[1])},(_,i)=>`<circle class="branch-pin ${i>=t.branches[0]?'branch-rival':''}" cx="${x-29+i*12}" cy="${y-20}" r="4"/>`).join('');return`<g opacity="${t.unlocked?1:.72}">${base}${park}${buildings}${pins}</g>`}
// Cheapest branch model this seat could re-enter a market with, priced locally
// rather than at the catalogue default.
function marketReentryCost(v,market){
 const costs=Object.entries(E.projectCatalog(v.me,v)).filter(([,def])=>def.kind==='branch'&&!def.legacy).map(([key])=>key)
  .map(key=>E.projectStartTerms(v,v.me,key,market)?.cost)
  .filter(n=>Number.isFinite(n)&&n>0);
 return costs.length?Math.min(...costs):E.PROJECTS.branch.cost;
}
function renderMarkets(v){const inspected=inspectedMarket(v);renderFacilityNetwork(v);if(v.me.facilityLifecycle)renderFacilityLifecycle(v);else{const lifecycleMount=$('#facilityLifecyclePanel');if(lifecycleMount){lifecycleMount.innerHTML='';lifecycleMount.classList.add('hidden')}}$('#marketTitle').textContent=v.campaignRulesVersion===1?'TWO-REGION MARKET NETWORK':'THE CITY';const locked=Object.values(v.territories).filter(t=>!t.unlocked),next=locked.sort((a,b)=>a.unlock-b.unlock)[0];$('#unlockText').textContent=v.campaignRulesVersion===1?'ALL SIX MARKETS OPEN · PAID RE-ENTRY AVAILABLE':next?`NEXT DISTRICTS OPEN: CYCLE ${next.unlock}`:'THE ENTIRE CITY IS OPEN';const entries=Object.entries(v.territories),roads=MAP_LINKS.filter(([a,b])=>v.territories[a]&&v.territories[b]).map(([a,b])=>{const A=mapPosition(a,v.territories[a]),B=mapPosition(b,v.territories[b]),x1=A[0]*10,y1=A[1]*6.5,x2=B[0]*10,y2=B[1]*6.5,fade=v.territories[a].unlocked&&v.territories[b].unlocked?1:.45;return`<g opacity="${fade}"><line class="city-road-edge" x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}"/><line class="city-road" x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}"/></g>`}).join(''),districts=entries.map(([k,t])=>districtArt(k,t)).join(''),nodes=marketEntries(v).map(([k,t])=>{const exitLimit=v.regionalEconomyVersion===1?6:3,streak=(t.exitStreak&&t.exitStreak[0])||0,withdrawn=!!(t.exited&&t.exited[0]),risk=!withdrawn&&streak>0?`<div class="market-risk ${streak>=exitLimit-1?'critical':'warning'}">AT RISK ${streak}/${exitLimit} · below 12% share</div>`:'',reentry=withdrawn?`<div class="market-risk withdrawn">${[8,9,10].includes(v.financialGroupVersion)?`WITHDRAWN · re-enter from ${money(marketReentryCost(v,k))}`:'WITHDRAWN · inspect campaign restrictions'}</div>`:'',[label,cls]=ownerLabel(t.shares[0]),p=mapPosition(k,t),models=(t.facilityModels||[]).map(type=>`<span class="facility-chip ${type}">${type==='retail'?'FULL SERVICE':type.toUpperCase()}</span>`).join('');return`<button type="button" class="market-node ${cls} ${inspected===k?'selected':''} ${t.unlocked?'':'locked'} ${withdrawn?'withdrawn':streak>0?'at-risk':''}" style="left:${p[0]}%;top:${Math.min(91,p[1]+7)}%" data-market="${k}" aria-label="${esc(t.name)}, ${label}, your share ${t.shares[0].toFixed(1)} percent" aria-pressed="${inspected===k}"><div class="node-head"><span class="share-ring" style="--share:${t.shares[0]}"></span><div><div class="market-name">${esc(t.name)}</div><div class="node-share">YOU ${t.shares[0].toFixed(1)}% · RIVAL ${t.shares[1].toFixed(1)}%</div></div></div><div class="node-meta"><span>VALUE ${t.value}</span><span>FACILITIES ${t.branches[0]}:${t.branches[1]}</span><span>${t.unlocked?label:`OPENS ${t.unlock}`}</span></div>${models?`<div class="facility-key">${models}</div>`:''}${risk}${reentry}</button>`}).join('');$('#marketMap').innerHTML=`<div class="map-board"><svg class="map-routes" viewBox="0 0 1000 650" preserveAspectRatio="xMidYMid meet" aria-hidden="true"><defs><linearGradient id="waterFade" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#bce2f2"/><stop offset="1" stop-color="#7dbbd9"/></linearGradient></defs><path class="city-water" fill="url(#waterFade)" d="M690,0 H1000 V650 H820 C875,535 760,446 806,342 846,251 752,151 690,0Z"/><polygon class="city-ground" points="55,275 330,46 825,116 950,408 710,620 190,572"/><polygon class="city-block" points="120,286 336,86 525,113 320,305"/><polygon class="city-block" points="339,322 548,126 768,157 565,350"/><polygon class="city-block" points="594,364 786,182 900,405 715,574"/><polygon class="city-block" points="148,324 310,340 538,555 207,531"/>${roads}${districts}<ellipse cx="505" cy="362" rx="230" ry="118" fill="none" stroke="#91b7aa" stroke-width="2" stroke-dasharray="7 8" opacity=".65"/></svg>${nodes}</div><div class="legend"><span><i class="l-me"></i>YOU · ${esc(v.me.name)} · SOLID</span><span><i class="l-rival"></i>RIVAL · ${esc(v.rival.name)} · DASHED</span><span><i class="l-contested"></i>CONTESTED DISTRICT</span><span>RING = ${v.marketEconomyVersion===1?'INFLUENCE, NOT DEPOSITS':'MARKET SHARE'}</span><span>FACILITIES = YOU:RIVAL</span></div><details class="market-region-details"><summary>Regional books, ownership &amp; network totals</summary>${renderRegionSummary(v)}</details>`;renderMarketInspector(v);const token=marketActionToken(v);$$('button[data-market]').forEach(b=>b.addEventListener('click',()=>{if(marketActionCurrent(token,false))inspectMarket(v,b.dataset.market)}))}
